#define BB_START       0x42000000U

#define CALC_BB_ADDR(base, offs, bitNo)        ((Taddr)(((Taddr)((Taddr)(base + offs - SFR_START)*32u)) + (4u * (uint8_t)bitNo)) + BB_START)
#define CALC_ADDR(base, offs)                  (Taddr)(base + offs)


#define SFR_Reg(base,offs,type)                ((*(type*)((base) + (offs))).tReg)
#define SFR_Bit(base,offs,type,bit)            ((*(type*)((base) + (offs))).tBits.bit)
#define SFR_BitBand(base,offs,type,bit,bitNo)  (*(volatile Treg32*)(CALC_BB_ADDR(base, offs, bitNo)))

