#define CAN_MCR_IDAM(base)           (__CAN_MCR.tBits.bfIdam)              ///< ID Acceptance Mode
#define CAN_MCR_AEN(base)            (__CAN_MCR.tBits.bfAen)               ///< Abort Enable
#define CAN_MCR_LPRIOEN(base)        (__CAN_MCR.tBits.bfLprioen)           ///< Local Priority Enable
#define CAN_MCR_DMA(base)            (__CAN_MCR.tBits.bfDma)               ///< DMA Enable
#define CAN_MCR_IRMQ(base)           (__CAN_MCR.tBits.bfIrmq)              ///< Individual Rx Masking And Queue Enable
#define CAN_MCR_SRXDIS(base)         (__CAN_MCR.tBits.bfSrxdis)            ///< Self Reception Disable
#define CAN_MCR_DOZE(base)           (__CAN_MCR.tBits.bfDoze)              ///< Doze Mode Enable
