#define CAN_MCR_HALT(base)           (__CAN_MCR.tBits.bfHalt)              ///< Halt FlexCAN
#define CAN_MCR_RFEN(base)           (__CAN_MCR.tBits.bfRfen)              ///< Rx FIFO Enable
#define CAN_MCR_FRZ(base)            (__CAN_MCR.tBits.bfFrz)               ///< Freeze Enable
#define CAN_MCR_MDIS(base)           (__CAN_MCR.tBits.bfMdis)              ///< Module Disable

