            Treg32 bfWaksrc              : 1;  ///< Wake Up Source
            Treg32 bfLpmack              : 1;  ///< Low-Power Mode Acknowledge
            Treg32 bfWrnen               : 1;  ///< Warning Interrupt Enable
            Treg32 bfSlfwak              : 1;  ///< Self Wake Up
            Treg32 bfSupv                : 1;  ///< Supervisor Mode
            Treg32 bfFrzack              : 1;  ///< Freeze Mode Acknowledge
            Treg32 bfSoftrst             : 1;  ///< Soft Reset
            Treg32 bfWakmsk              : 1;  ///< Wake Up Interrupt Mask
            Treg32 bfNotrdy              : 1;  ///< FlexCAN Not Ready
            Treg32 bfHalt                : 1;  ///< Halt FlexCAN
            Treg32 bfRfen                : 1;  ///< Rx FIFO Enable
